    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
    color: #dcddde;
}

::deep .thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #4f545c;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

::deep .thread-reply {
    padding: 6px 0;
}

::deep .thread-reply .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

/* Layout adjustments when thread is open */
.chat-layout.thread-open ::deep .message-area {
    width: 55%;
}
"}

